    r'''{"n":1,"dates":"19/10→25/10/2026","block":"Bloc A — Densité et volume","blockKey":"NA","color":"6B0C0C","days":[{"j":1,"title":"TIRAGE LOURD + MUSCLE-UP","cycle":"accumulation 1/4","conduite":"CONDUITE J1 — Force max du tirage. Muscle-up lesté frais, puis traction lourde au départ chronométré avec les pompes dans la pause, rowing et poignets en séries classiques, finisher face pulls + curl marteau (dernier tour à l’échec). Réussite : toutes les reps lourdes rapides, aucune grindée. | Échauffement 12 min : 5 min de cardio léger → mobilité épaules, poignets, hanches → 2×10 scap pulls / scap push-ups → montée en charge du premier exercice (3-4 séries courtes, jamais à l’échec).","exercises":[{"id":"NA-S15J1-01","name":"MUSCLE-UP LESTÉ — lift n°1, frais","sets":{"type":"text","value":"6×2 · E2MOM"},"intensity":"RIR 2,5 · ~89 % système","load":{"type":"system","ref":"B10","pct":0.89},"rest":"Départ toutes les 2 min","restSec":120,"tempo":"Intention maximale","cue":"Premier exercice, avant tout tirage, frais. Départ au top de chaque intervalle : prise fausse prise ou classique, tirage explosif vers le bas des pectoraux, transition rapide, verrouillage bras tendus. Le reste de l’intervalle est ton repos. 1re rep moche ou lente → baisse de 2,5 kg pour la suite. Jamais de rep grindée. Charge visée ≈ 7.5 kg.","main":true,"prevention":false,"catalogId":"sl-muscle-up-leste"},{"id":"NA-S15J1-02","name":"TRACTION LESTÉE — lift principal","sets":{"type":"text","value":"8×3 · E2MOM"},"intensity":"RIR 2 · ~83 % système","load":{"type":"system","ref":"B8","pct":0.83},"rest":"Départ toutes les 2 min","restSec":120,"tempo":"Intention maximale","cue":"Pronation largeur d’épaules, départ bras tendus, menton au-dessus de la barre, descente contrôlée jusqu’en bas. Départ au top de chaque intervalle ; dès que tu lâches la barre, enchaîne les pompes de la ligne suivante. Arrête la ligne si une rep ralentit nettement : la qualité prime sur le nombre de tours. Charge visée ≈ 35 kg.","main":true,"prevention":false,"catalogId":"sl-traction-lestee"},{"id":"NA-S15J1-03","name":"Pompes PdC — pause de la traction, enchaîné","sets":{"type":"volume","prefix":"8×","coef":1.391,"ref":"B19","div":8,"suffix":" · E2MOM"},"intensity":"RIR 5+ · très facile","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Remplissage de la pause, pas un exercice de fatigue : pompes propres, très loin de l’échec, dans les 30 s qui suivent la traction. C’est du « grease the groove » pour ton objectif pompes : de la fréquence sans coût sur la traction lourde.","main":false,"prevention":false,"catalogId":"sw-pompe"},{"id":"NA-S15J1-04","name":"Rowing barre penché","sets":{"type":"text","value":"3×8"},"intensity":"RIR 2","load":{"type":"acc","ref":"B25","dayReps":8,"step":2.5},"rest":"2 min","restSec":120,"tempo":"1 s de pause en haut","cue":"Séries classiques. Buste à 45°, dos plat, barre au nombril, omoplates serrées en haut. Construit le haut de la traction (fin de tirage) et la tirée explosive du muscle-up.","main":false,"prevention":false,"catalogId":"mu-rowing-barre-pronation"},{"id":"NA-S15J1-05","name":"Poignets excentriques (haltère)","sets":{"type":"text","value":"3×15 (flex. + ext.)"},"intensity":"RIR 3 — descente 3 s","load":{"type":"acc","ref":"B45","dayReps":15,"step":1.0},"rest":"60 s","restSec":60,"tempo":"3 s exc.","cue":"Séries classiques. Tendons du coude et du poignet (HSR) : 3 s de descente comptées, jamais à l’échec (le tendon se renforce par la charge lente, pas par la fatigue). Indispensable avec le volume de suspension du programme.","main":false,"prevention":false,"catalogId":"mu-reverse-wrist-curl-haltere"},{"id":"NA-S15J1-06","name":"Face pulls (poulie) — finisher","sets":{"type":"text","value":"3×15"},"intensity":"RIR 2","load":{"type":"acc","ref":"B43","dayReps":15,"step":2.5},"rest":"enchaîné → curl","restSec":0,"tempo":"1 s de pause","cue":"Finisher en superset, en fin de séance : enchaîne directement avec l’exercice suivant (poulie puis haltères posés à côté), puis prends le repos indiqué sous le second. Coudes hauts, rotation externe complète en fin de course. Prévention épaule obligatoire avec ce volume de tirage et de muscle-up.","main":false,"prevention":true,"catalogId":"mu-face-pull-corde"},{"id":"NA-S15J1-07","name":"Curl marteau (par haltère) — finisher, enchaîné","sets":{"type":"text","value":"3×10"},"intensity":"RIR 1 · dernier tour jusqu’à l’échec","load":{"type":"acc","ref":"B30","dayReps":10,"step":2.0},"rest":"90 s","restSec":90,"tempo":"Contrôlé","cue":"Prise neutre : brachial et long supinateur, les muscles de la transition du muscle-up et la protection du coude. Dernier tour jusqu’à l’échec propre (sans élan) : tu finis la séance cramé sans toucher au lourd de la semaine.","main":false,"prevention":false,"catalogId":"mu-curl-marteau-halteres"}]},{"j":2,"title":"POUSSÉE LOURDE — DIPS","cycle":"accumulation 1/4","conduite":"CONDUITE J2 — Force max de la poussée. Dip lourd au départ chronométré avec les tractions dans la pause, pompes lestées et épaules en séries classiques, finisher triceps + élévations. Réussite : profondeur réglementaire sur toutes les reps de dip. | Échauffement 12 min : 5 min de cardio léger → mobilité épaules, poignets, hanches → 2×10 scap pulls / scap push-ups → montée en charge du premier exercice (3-4 séries courtes, jamais à l’échec).","exercises":[{"id":"NA-S15J2-01","name":"DIP LESTÉ — lift principal","sets":{"type":"text","value":"8×3 · E2MOM"},"intensity":"RIR 2,5 · ~82 % système","load":{"type":"system","ref":"B9","pct":0.82},"rest":"Départ toutes les 2 min","restSec":120,"tempo":"Intention maximale","cue":"Profondeur compétition (épaule sous le coude), omoplates verrouillées, remontée explosive jusqu’au verrouillage. Départ au top de chaque intervalle ; dès la ceinture posée, enchaîne les tractions de la ligne suivante. Une rep qui perd la profondeur met fin à la série. Charge visée ≈ 50 kg.","main":true,"prevention":false,"catalogId":"sl-dips-leste"},{"id":"NA-S15J2-02","name":"Tractions PdC — pause du dip, enchaîné","sets":{"type":"volume","prefix":"8×","coef":1.6,"ref":"B17","div":8,"suffix":" · E2MOM"},"intensity":"RIR 5+ · très facile","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Remplissage de la pause : tractions PdC propres, très loin de l’échec, juste après le dip. Même logique « grease the groove » pour ton objectif tractions, sans coût sur la poussée lourde (muscles opposés).","main":false,"prevention":false,"catalogId":"sw-traction-pronation"},{"id":"NA-S15J2-03","name":"Pompes lestées (lest ajouté)","sets":{"type":"text","value":"4×6"},"intensity":"RIR 2","load":{"type":"acc","ref":"B36","dayReps":6,"step":2.5},"rest":"2 min","restSec":120,"tempo":"Descente contrôlée, poussée explosive","cue":"Gilet ou disques sur le haut du dos, corps gainé, poitrine au sol à chaque rep. Ta référence de charge date un peu : si la 1re série sort à RIR 4 ou plus, ajoute 5 kg dès la 2e.  La force en pompe lestée rend tes pompes au poids du corps plus faciles (réserve) et soutient le dip lourd.","main":false,"prevention":false,"catalogId":"sl-pompe-lestee-gilet"},{"id":"NA-S15J2-04","name":"Développé militaire debout","sets":{"type":"text","value":"3×8"},"intensity":"RIR 2","load":{"type":"acc","ref":"B31","dayReps":8,"step":2.5},"rest":"2 min","restSec":120,"tempo":"Contrôlé","cue":"Séries classiques. Fessiers et abdos serrés, pas de cambrure. Épaules fortes au-dessus de la tête : verrouillage du muscle-up et stabilité en haut du dip.","main":false,"prevention":false,"catalogId":"mu-developpe-militaire-barre-debout"},{"id":"NA-S15J2-05","name":"Rotations externes (par haltère)","sets":{"type":"text","value":"2×15/bras"},"intensity":"RIR 3","load":{"type":"acc","ref":"B44","dayReps":15,"step":1.0},"rest":"60 s","restSec":60,"tempo":"Contrôlé","cue":"Coiffe des rotateurs : coude collé, amplitude complète, léger. Prévention épaule face au volume de dips du programme.","main":false,"prevention":true,"catalogId":"mu-rotation-externe-haltere-couche"},{"id":"NA-S15J2-06","name":"Extension triceps poulie corde — finisher","sets":{"type":"text","value":"3×12"},"intensity":"RIR 1 · dernier tour jusqu’à l’échec","load":{"type":"acc","ref":"B34","dayReps":12,"step":2.5},"rest":"enchaîné → élévations","restSec":0,"tempo":"Coudes fixes","cue":"Finisher en superset, en fin de séance : enchaîne directement avec l’exercice suivant (poulie puis haltères posés à côté), puis prends le repos indiqué sous le second. Extension complète, écarte la corde en bas. Le triceps est le facteur limitant de tes longues séries de dips.","main":false,"prevention":false,"catalogId":"mu-pushdown-corde"},{"id":"NA-S15J2-07","name":"Élévations latérales (par haltère) — finisher, enchaîné","sets":{"type":"text","value":"3×15"},"intensity":"RIR 1 · dernier tour jusqu’à l’échec","load":{"type":"acc","ref":"B33","dayReps":15,"step":1.0},"rest":"90 s","restSec":90,"tempo":"Contrôlé","cue":"Deltoïde moyen : stabilité de l’épaule sous charge. Pas d’élan de tronc, monte jusqu’à l’horizontale. Muscle différent du triceps : aucune perte sur l’un ou l’autre.","main":false,"prevention":false,"catalogId":"mu-elevation-laterale-halteres"}]},{"j":3,"title":"JAMBES LOURD — SQUAT","cycle":"accumulation 1/4","conduite":"CONDUITE J3 — Squat lourd toutes les 3 min avec le dead hang dans la pause, chaîne postérieure, fentes et leg curl en séries classiques, finisher cardio. Réussite : même vitesse sur la dernière série que sur la première. | Échauffement 12 min : 5 min de cardio léger → mobilité épaules, poignets, hanches → 2×10 scap pulls / scap push-ups → montée en charge du premier exercice (3-4 séries courtes, jamais à l’échec).","exercises":[{"id":"NA-S15J3-01","name":"BACK SQUAT — lift principal","sets":{"type":"text","value":"6×3 · E3MOM"},"intensity":"RIR 3 · ~80 % barre","load":{"type":"barbell","ref":"B11","pct":0.8},"rest":"Départ toutes les 3 min","restSec":180,"tempo":"Intention maximale","cue":"Profondeur compétition (pli de hanche sous le genou), dos neutre, gainage bloqué avant chaque rep, poussée milieu du pied. Départ au top de chaque intervalle de 3 min ; entre deux séries, la ligne suivante (dead hang) décompresse le dos. Rack de sécurité réglé. Charge visée ≈ 95 kg.","main":true,"prevention":false,"catalogId":"sl-squat-competition"},{"id":"NA-S15J3-02","name":"Dead hang PdC — pause du squat, enchaîné","sets":{"type":"text","value":"6×30 s"},"intensity":"Facile","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Dans la pause du squat : suspension bras tendus, épaules actives. Décompresse la colonne après chaque série et entraîne la prise, souvent ce qui lâche en premier sur une longue série de tractions.","main":false,"prevention":false,"catalogId":"sw-dead-hang"},{"id":"NA-S15J3-03","name":"Soulevé de terre roumain","sets":{"type":"text","value":"3×8"},"intensity":"RIR 2","load":{"type":"acc","ref":"B37","dayReps":8,"step":2.5},"rest":"2 min 30","restSec":150,"tempo":"Descente 2 s","cue":"Dos neutre, barre au contact des cuisses, hanches vers l’arrière jusqu’à l’étirement des ischios. Chaîne postérieure du squat et protection du bas du dos.","main":false,"prevention":false,"catalogId":"mu-souleve-de-terre-roumain-barre"},{"id":"NA-S15J3-04","name":"Fentes marchées (par haltère)","sets":{"type":"text","value":"3×10/jambe"},"intensity":"RIR 2","load":{"type":"acc","ref":"B38","dayReps":10,"step":2.0},"rest":"2 min","restSec":120,"tempo":"Contrôlé","cue":"Séries classiques. Grand pas, genou arrière proche du sol, buste droit. Le travail unilatéral corrige les déséquilibres que le squat cache.","main":false,"prevention":false,"catalogId":"mu-fente-marchee-halteres"},{"id":"NA-S15J3-05","name":"Leg curl (machine)","sets":{"type":"text","value":"3×12"},"intensity":"RIR 1","load":{"type":"acc","ref":"B39","dayReps":12,"step":2.5},"rest":"90 s","restSec":90,"tempo":"Contrôlé","cue":"Ischios : l’assurance anti-blessure du squat lourd. Pause 1 s en contraction.","main":false,"prevention":false,"catalogId":"mu-leg-curl-couche"},{"id":"NA-S15J3-06","name":"Intervalles air bike ou rameur — finisher","sets":{"type":"text","value":"8× (30 s effort / 30 s repos)"},"intensity":"Intense","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Finisher court : capacité de travail et récupération entre les séries (utile pour tes EMOM), sans cardio long qui gênerait la force. Effort franc sur chaque intervalle, même allure du premier au dernier.","main":false,"prevention":false,"catalogId":"ca-air-bike-sprints"},{"id":"NA-S15J3-07","name":"GtG muscle-up — dans la journée","sets":{"type":"text","value":"3×4"},"intensity":"Très facile","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Trois séries de 4 muscle-ups PdC parfaits réparties dans la journée (hors séance), jamais près de l’échec. Fréquence = technique plus économique = plus de reps en test.","main":false,"prevention":false,"catalogId":"cd-muscle-up-barre-strict"}]},{"j":4,"title":"TIRAGE DENSITÉ + ENDURANCE","cycle":"accumulation 1/4","conduite":"CONDUITE J4 — Tirage dense : muscle-ups en EMOM frais, contraste lourd → explosif, tractions en EMOM, rowing en séries classiques, puis zone rouge. Réussite : aucune minute ratée avant la dernière, zone rouge terminée sans tricher sur l’amplitude. | Échauffement 12 min : 5 min de cardio léger → mobilité épaules, poignets, hanches → 2×10 scap pulls / scap push-ups → montée en charge du premier exercice (3-4 séries courtes, jamais à l’échec).","exercises":[{"id":"NA-S15J4-01","name":"Muscle-ups PdC — EMOM technique","sets":{"type":"volume","prefix":"EMOM 8 min × ","coef":2.4,"ref":"B16","div":8,"suffix":" reps par minute"},"intensity":"RIR 3 par minute","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Au début de la séance, frais. Départ au top de chaque minute, reps parfaites (pas de kipping inutile, transition propre). Volume de qualité vers tes 16 muscle-ups : deux minutes ratées d’affilée → stop.","main":false,"prevention":false,"catalogId":"cd-muscle-up-barre-strict"},{"id":"NA-S15J4-02","name":"TRACTION LESTÉE — contraste, lourd","sets":{"type":"text","value":"6×2 · E2MOM"},"intensity":"RIR 3 · ~84 % système","load":{"type":"system","ref":"B8","pct":0.84},"rest":"Départ toutes les 2 min","restSec":120,"tempo":"Intention maximale","cue":"Contraste (force utile) : la série lourde potentialise, les tractions explosives de la ligne suivante exploitent cette fenêtre. Fais les reps lourdes, retire la ceinture tout de suite et enchaîne. Charge visée ≈ 37.5 kg.","main":true,"prevention":false,"catalogId":"sl-traction-lestee"},{"id":"NA-S15J4-03","name":"Tractions explosives poitrine-barre — contraste, enchaîné","sets":{"type":"text","value":"6×4 · E2MOM"},"intensity":"Vitesse maximale","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"Explosif","cue":"Poitrine à la barre, montée la plus rapide possible, descente contrôlée. Arrête la série dès qu’une rep ralentit : on cherche la vitesse, pas la fatigue.","main":false,"prevention":false,"catalogId":"cd-traction-explosive-poitrine-barre"},{"id":"NA-S15J4-04","name":"Tractions PdC — EMOM","sets":{"type":"volume","prefix":"EMOM 10 min × ","coef":2.667,"ref":"B17","div":10,"suffix":" reps par minute"},"intensity":"RIR 3 par minute","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Départ au top de chaque minute, amplitude complète, même vitesse du début à la fin. Volume indexé sur ton max réel (il suit tes tests). Deux minutes ratées d’affilée → stop et note la minute atteinte.","main":false,"prevention":false,"catalogId":"sw-traction-pronation"},{"id":"NA-S15J4-05","name":"Rowing haltère unilatéral (par haltère)","sets":{"type":"text","value":"3×10"},"intensity":"RIR 2","load":{"type":"acc","ref":"B28","dayReps":10,"step":2.0},"rest":"90 s","restSec":90,"tempo":"1 s en haut","cue":"Séries classiques. Coude vers la hanche, pas d’élan du buste. Grand dorsal en amplitude complète, chaque côté indépendant.","main":false,"prevention":false,"catalogId":"mu-rowing-haltere-unilateral-banc"},{"id":"NA-S15J4-06","name":"ZONE ROUGE — drop set mécanique tirage","sets":{"type":"text","value":"2 tours × 4 paliers"},"intensity":"Échec sur les paliers 3 et 4","load":{"type":"fixed","kg":0.0},"rest":"3 min","restSec":180,"tempo":"≤ 10 s entre paliers","cue":"Dernier exercice, rien de lourd après. Un tour = 4 paliers enchaînés en moins de 10 s : 1. tractions pronation PdC jusqu’à RIR 1 → 2. rows australiens jusqu’à RIR 1 → 3. tenue menton au-dessus de la barre jusqu’à l’échec → 4. dead hang jusqu’à l’échec. Note les reps (paliers 1-2) et les secondes (paliers 3-4) sur chaque ligne. 3 min entre les tours.","main":false,"prevention":false,"catalogId":"sw-traction-pronation"}]},{"j":5,"title":"POUSSÉE DENSITÉ + ENDURANCE","cycle":"accumulation 1/4","conduite":"CONDUITE J5 — Poussée dense : contraste lourd → explosif, dips en EMOM, barre au front et face pulls en séries classiques, puis zone rouge. Réussite : profondeur complète jusqu’à la dernière minute de l’EMOM. | Échauffement 12 min : 5 min de cardio léger → mobilité épaules, poignets, hanches → 2×10 scap pulls / scap push-ups → montée en charge du premier exercice (3-4 séries courtes, jamais à l’échec).","exercises":[{"id":"NA-S15J5-01","name":"DIP LESTÉ — contraste, lourd","sets":{"type":"text","value":"6×2 · E2MOM"},"intensity":"RIR 3 · ~84 % système","load":{"type":"system","ref":"B9","pct":0.84},"rest":"Départ toutes les 2 min","restSec":120,"tempo":"Intention maximale","cue":"Contraste (force utile) : reps lourdes à profondeur compétition, ceinture retirée tout de suite, puis les dips explosifs de la ligne suivante. Charge visée ≈ 52.5 kg.","main":true,"prevention":false,"catalogId":"sl-dips-leste"},{"id":"NA-S15J5-02","name":"Dips explosifs mains décollées — contraste, enchaîné","sets":{"type":"text","value":"6×5 · E2MOM"},"intensity":"Vitesse maximale","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"Explosif","cue":"Poussée maximale pour décoller les mains en haut (ou au moins chercher la vitesse maximale). Réception souple, descente contrôlée. Stop dès que la vitesse baisse.","main":false,"prevention":false,"catalogId":"cd-dips-explosifs"},{"id":"NA-S15J5-03","name":"Dips PdC — EMOM","sets":{"type":"volume","prefix":"EMOM 12 min × ","coef":3.086,"ref":"B18","div":12,"suffix":" reps par minute"},"intensity":"RIR 3 par minute","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Départ au top de chaque minute, profondeur complète, cadence régulière. Volume indexé sur ton max réel. Deux minutes ratées d’affilée → stop et note la minute atteinte.","main":false,"prevention":false,"catalogId":"sw-dips-barres-paralleles"},{"id":"NA-S15J5-04","name":"Barre au front EZ","sets":{"type":"text","value":"3×10"},"intensity":"RIR 2","load":{"type":"acc","ref":"B35","dayReps":10,"step":2.5},"rest":"2 min","restSec":120,"tempo":"Descente 2 s","cue":"Séries classiques. Coudes fixes, barre derrière le front. Chef long du triceps : le verrouillage du dip. Douleur au coude → remplace par l’extension à la poulie.","main":false,"prevention":false,"catalogId":"mu-barre-au-front-ez"},{"id":"NA-S15J5-05","name":"Face pulls (poulie)","sets":{"type":"text","value":"2×15"},"intensity":"RIR 3","load":{"type":"acc","ref":"B43","dayReps":15,"step":2.5},"rest":"60 s","restSec":60,"tempo":"1 s de pause","cue":"Équilibre de l’épaule après un gros volume de poussée. Léger, coudes hauts.","main":false,"prevention":true,"catalogId":"mu-face-pull-corde"},{"id":"NA-S15J5-06","name":"ZONE ROUGE — drop set mécanique poussée","sets":{"type":"text","value":"2 tours × 5 paliers"},"intensity":"Échec sur le dernier palier","load":{"type":"fixed","kg":0.0},"rest":"3 min","restSec":180,"tempo":"≤ 10 s entre paliers","cue":"Dernier exercice. Un tour = 5 paliers enchaînés en moins de 10 s, du plus dur au plus facile : 1. dips PdC jusqu’à RIR 1 → 2. pompes pieds surélevés jusqu’à RIR 1 → 3. pompes diamant jusqu’à RIR 1 → 4. pompes classiques jusqu’à RIR 0 → 5. pompes mains surélevées jusqu’à l’échec. Note les reps de chaque palier. 3 min entre les tours.","main":false,"prevention":false,"catalogId":"sw-dips-barres-paralleles"}]},{"j":6,"title":"JAMBES ENDURANCE — SQUAT 70 KG","cycle":"accumulation 1/4","conduite":"CONDUITE J6 — Squat pause lourd modéré, puis endurance à 70 kg, hip thrust et gainage en séries classiques, finisher cardio. Réussite : toutes les reps à 70 kg à profondeur compétition. | Échauffement 12 min : 5 min de cardio léger → mobilité épaules, poignets, hanches → 2×10 scap pulls / scap push-ups → montée en charge du premier exercice (3-4 séries courtes, jamais à l’échec).","exercises":[{"id":"NA-S15J6-01","name":"Squat pause 2 s","sets":{"type":"text","value":"3×3"},"intensity":"RIR 3 · ~75 % barre","load":{"type":"barbell","ref":"B11","pct":0.75},"rest":"2 min 30","restSec":150,"tempo":"2 s de pause en bas","cue":"Deuxième exposition lourde de la semaine, sans fatigue : 2 s immobile en bas, gainage tenu, puis remontée explosive. Force dans la position la plus difficile de la profondeur compétition. Charge visée ≈ 90 kg.","main":false,"prevention":false,"catalogId":"mu-squat-pause"},{"id":"NA-S15J6-02","name":"Squat endurance @ 70 kg","sets":{"type":"volume","prefix":"3 × ","coef":2.16,"ref":"B20","div":3,"suffix":" reps"},"intensity":"RIR 2 sur la dernière série","load":{"type":"fixed","kg":70.0},"rest":"3 min","restSec":180,"tempo":"Cadence régulière","cue":"Charge fixe 70 kg. Respiration à chaque rep en haut, rythme constant, profondeur compétition sur toutes les reps. Volume indexé sur ton max à 70 kg (il suit tes tests). Jamais à l’échec avec une barre sur le dos.","main":false,"prevention":false,"catalogId":"sl-squat-competition"},{"id":"NA-S15J6-03","name":"Hip thrust","sets":{"type":"text","value":"3×10"},"intensity":"RIR 2","load":{"type":"acc","ref":"B40","dayReps":10,"step":2.5},"rest":"2 min","restSec":120,"tempo":"1 s en haut","cue":"Séries classiques. Menton rentré, bassin en rétroversion en haut. Fessiers : la sortie du trou au squat.","main":false,"prevention":false,"catalogId":"mu-hip-thrust-barre"},{"id":"NA-S15J6-04","name":"Leg raises lestés (suspendu)","sets":{"type":"text","value":"3×10"},"intensity":"RIR 2","load":{"type":"acc","ref":"B42","dayReps":10,"step":1.0},"rest":"90 s","restSec":90,"tempo":"Contrôlé","cue":"Sans balancer, bassin enroulé en haut. Gainage en suspension et compression : utiles au muscle-up et aux longues séries de tractions.","main":false,"prevention":false,"catalogId":"sl-releve-jambes-suspendu-leste"},{"id":"NA-S15J6-05","name":"Intervalles rameur — finisher","sets":{"type":"text","value":"6× (40 s effort / 20 s repos)"},"intensity":"Intense","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Deuxième finisher cardio de la semaine : 40 s fortes / 20 s de récupération. Garde la même distance sur chaque effort.","main":false,"prevention":false,"catalogId":"ca-rameur-sprint"},{"id":"NA-S15J6-06","name":"GtG muscle-up — dans la journée","sets":{"type":"text","value":"3×4"},"intensity":"Très facile","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Trois séries de 4 muscle-ups PdC parfaits réparties dans la journée, jamais près de l’échec.","main":false,"prevention":false,"catalogId":"cd-muscle-up-barre-strict"},{"id":"NA-S15J6-07","name":"Mobilité épaules + poignets","sets":{"type":"text","value":"10 min"},"intensity":"Doux","load":{"type":"fixed","kg":0.0},"rest":"—","restSec":null,"tempo":"","cue":"Dislocations au bâton, étirements des extenseurs du poignet, pectoraux et dorsaux. Prépare la semaine suivante.","main":false,"prevention":false,"catalogId":"mo-routine-mobilite-epaules-poignets"}]},{"j":7,"title":"REPOS COMPLET","cycle":"","conduite":"REPOS COMPLET · marche, mobilité légère, sommeil maximum. GtG suspendu.","exercises":[]}]}''';
